class TestExplicitClaims(unittest.TestCase):
    def test_claim_collection_allows_identical_duplicate_emissions(self):
        claims = claim_mod.ClaimCollection()

        payload1 = claims.claim(
            "mp.plus.example.same-record",
            {"row": 1},
            kind="example",
            subject="mp:plus",
            data={"x": 1},
        )
        payload2 = claims.claim(
            "mp.plus.example.same-record",
            {"row": 2},
            kind="example",
            subject="mp:plus",
            data={"x": 1},
        )

        self.assertEqual(payload1, {"row": 1})
        self.assertEqual(payload2, {"row": 2})
        self.assertEqual(len(claims.records_by_id), 1)
        self.assertEqual(len(claims.emissions), 2)

    def test_claim_collection_duplicate_emissions_preserve_defined_in_provenance(self):
        claims = claim_mod.ClaimCollection()
        claim_id = "mp.both.templates.kq-special.subtypes"
        common = {
            "kind": "enum",
            "subject": "mp:both",
            "data": {"allowed": ["ctor", "func"]},
        }

        claims.emit(
            claim_mod.make_record(
                claim_id,
                **common,
                defined_in="author_misc.mp_cmn",
            )
        )
        claims.emit(
            claim_mod.make_record(
                claim_id,
                **common,
                defined_in="author.mpplus_kq_special",
            )
        )

        self.assertEqual(len(claims.records_by_id), 1)
        self.assertEqual(
            claims.records_by_id[claim_id].defined_in, "author_misc.mp_cmn"
        )
        self.assertEqual(len(claims.emissions), 2)
        self.assertEqual(claims.emissions[0].record.defined_in, "author_misc.mp_cmn")
        self.assertEqual(claims.emissions[1].record.defined_in, "author_misc.mp_cmn")
        self.assertEqual(
            [e.emitted_record.defined_in for e in claims.emissions],
            ["author_misc.mp_cmn", "author.mpplus_kq_special"],
        )

    def test_claim_collection_rejects_conflicting_duplicate_id(self):
        claims = claim_mod.ClaimCollection()
        claims.claim(
            "mp.plus.example.conflict",
            "first",
            kind="example",
            subject="mp:plus",
            data={"x": 1},
        )

        with self.assertRaisesRegex(
            ValueError,
            r"conflicting duplicate claim id: 'mp\.plus\.example\.conflict'",
        ):
            claims.claim(
                "mp.plus.example.conflict",
                "second",
                kind="example",
                subject="mp:plus",
                data={"x": 2},
            )

    def test_legacy_global_registry_api_is_removed(self):
        self.assertFalse(hasattr(claim_mod, "REGISTRY"))
        self.assertFalse(hasattr(claim_mod, "claim"))

    def test_claims_doc_generate_uses_explicit_claims(self):
        claims = claim_mod.ClaimCollection()
        claims.claim(
            "mp.plus.verse.is-3-tuple",
            "Each verse is a 3-element array [C, D, E].",
            kind="struct",
            subject="mp:plus",
            data={"shape": ["sep", "label", "text"]},
        )

        text = claims_doc.generate(claims)

        self.assertIn("| mp.plus.verse.is-3-tuple |", text)
        self.assertIn("| verify_mp_plus_verse_is_3_tuple |", text)

    def test_build_verifiers_uses_explicit_claims(self):
        claims = claim_mod.ClaimCollection()
        claims.claim(
            "mp.plus.verse.is-3-tuple",
            "payload",
            kind="struct",
            subject="mp:plus",
        )

        verifiers = driver.build_verifiers(claims)

        self.assertIn("mp.plus.verse.is-3-tuple", verifiers)
        self.assertEqual(
            verifiers["mp.plus.verse.is-3-tuple"].__name__,
            "verify_mp_plus_verse_is_3_tuple",
        )

    def test_build_verifiers_uses_registry_not_name_derivation(self):
        def verify_any_name(_record, _ctx):
            return None

        fake_module = SimpleNamespace(
            __name__="verify_mp.fake_registry",
            REGISTRY={"mp.plus.fake-claim": verify_any_name},
            verify_unrelated_symbol_name=verify_any_name,
        )
        claims = {
            "mp.plus.fake-claim": claim_mod.make_record(
                "mp.plus.fake-claim",
                kind="struct",
                subject="mp:plus",
                data={},
                defined_in="tests",
            )
        }

        with mock.patch.object(driver, "_VERIFIER_MODULES", (fake_module,)):
            verifiers = driver.build_verifiers(claims)

        self.assertEqual(verifiers, {"mp.plus.fake-claim": verify_any_name})

    def test_run_exits_on_stale_registry_keys(self):
        def verify_registered(_record, _ctx):
            return None

        fake_module = SimpleNamespace(
            __name__="verify_mp.fake_registry",
            REGISTRY={"mp.plus.fake-claim": verify_registered},
            verify_mp_fake_claim=verify_registered,
        )
        ctx = SimpleNamespace(claim_records=None)

        with mock.patch.object(driver, "_VERIFIER_MODULES", (fake_module,)):
            with self.assertRaises(SystemExit) as cm:
                driver.run(ctx, claims={})

        self.assertEqual(cm.exception.code, 2)

